"""parlist: prep lists and par-level reorders for small restaurants."""
from dataclasses import dataclass, field

@dataclass
class Item:
    name: str
    par: float      # target on-hand quantity
    on_hand: float
    unit: str
    supplier: str
    unit_cost: float = 0.0

    def to_order(self) -> float:
        return max(0.0, self.par - self.on_hand)

@dataclass
class Inventory:
    items: list = field(default_factory=list)

    def add(self, item: Item):
        self.items.append(item)

    def count(self, name: str, on_hand: float):
        for it in self.items:
            if it.name == name:
                it.on_hand = on_hand
                return
        raise KeyError(name)

