        return [(i.name, round(i.to_order(), 2), i.unit) for i in self.items if i.to_order() > 0]

    def supplier_orders(self):
        orders = {}
        for i in self.items:
            q = i.to_order()
            if q > 0:
                orders.setdefault(i.supplier, []).append((i.name, q, i.unit, round(q * i.unit_cost, 2)))
        return {s: {"lines": l, "total": round(sum(x[3] for x in l), 2)} for s, l in orders.items()}

