    inv.add(Item("rice", par=10, on_hand=6, unit="lb", supplier="Valley Foods", unit_cost=0.9))
    inv.add(Item("cilantro", par=6, on_hand=1, unit="bunch", supplier="Produce Co", unit_cost=0.75))
    print("Prep list:", inv.prep_list())
    for s, o in inv.supplier_orders().items():
        print(s, o)
