import math

# item: (avg daily use, lead time days, safety days, unit cost)
SAMPLE = {
    "chicken thigh (lb)": (14.0, 2, 1, 2.40),
    "rice (lb)":          (20.0, 3, 2, 0.85),
    "tortilla (pack)":    (9.0, 2, 1, 3.10),
    "cilantro (bunch)":   (6.0, 1, 1, 0.90),
}

def par_level(daily_use, lead_days, safety_days):
    return math.ceil(daily_use * (lead_days + safety_days))

def reorder_qty(par, on_hand):
    return max(0, par - on_hand)

if __name__ == "__main__":
    for item, (use, lead, safe, cost) in SAMPLE.items():
        p = par_level(use, lead, safe)
        print(f"{item:22s} par={p:4d} on_hand=0 order={reorder_qty(p, 0):4d} est=${reorder_qty(p,0)*cost:,.2f}")
